source.@value:
rule "fill message with event info"
when
  has_field("filebeat_event_type") || has_field("event_type") || has_field("rule")
then
  let rule_name = to_string($message.`rule`, "");
  let evt = to_string($message.event_type, rule_name);
  let et = to_string($message.filebeat_event_type, evt);
  let src = to_string($message.src_ip, "");
  let sip = to_string($message.source_ip, src);
  let ip = to_string($message.filebeat_source_ip, sip);
  set_field("message", concat(concat(et, "  |  src="), ip));
end
